import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Magic overview","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/magic.md","filePath":"en/game-design/magic.md"}'),r={name:"en/game-design/magic.md"};function o(s,e,l,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="magic-redesign-v0-1" tabindex="-1">Magic overview <a class="header-anchor" href="#magic-redesign-v0-1" aria-label="Permalink to &quot;Magic overview&quot;">​</a></h1><p><strong>Design status: Proposed. Numeric examples: tuning targets only. Implementation: this task changes documentation only; no magic-redesign implementation or runtime validation is established here.</strong></p><p>Recorded 2026-10-04 as a gameplay proposal. This is the canonical home for the proposal, not an approved implementation plan or a final spell catalogue. Existing Accepted foundations—server authority, <a href="/Syrolands-Public/en/game-design/combat/body-regions.html">global Hits and local integrity</a>, and <a href="/Syrolands-Public/en/game-design/combat/damage.html">separate Local Trauma</a>—remain in force. New magic mechanics below remain <strong>Proposed</strong> unless explicitly identified as an inherited foundation. Named institutions, spells, glyphs and stances are <strong>illustrative examples</strong>, not established world content.</p><h2 id="batch-04-reading-map" tabindex="-1">Batch 04 reading map <a class="header-anchor" href="#batch-04-reading-map" aria-label="Permalink to &quot;Batch 04 reading map&quot;">​</a></h2><p><strong>Reviewed 2026-10-09:</strong> the Batch 04 source expands this Proposed ecosystem. It does not approve implementation or supersede accepted combat foundations. <a href="/Syrolands-Public/en/guide/magic/overview.html">Player overview</a>.</p><table tabindex="0"><thead><tr><th>Owner</th><th>Scope</th></tr></thead><tbody><tr><td><a href="/Syrolands-Public/en/game-design/magic/spell-knowledge.html">Spell knowledge and Core Patterns</a></td><td>Learned identity, discovery and execution</td></tr><tr><td><a href="/Syrolands-Public/en/game-design/magic/variants-and-glyphs.html">Variants and glyphs</a></td><td>Bounded modifiers and compatibility</td></tr><tr><td><a href="/Syrolands-Public/en/game-design/magic/memory-and-familiarity.html">Familiarity and Active Memory</a></td><td>Practice, preparation, INT and reference under pressure</td></tr><tr><td><a href="#meditation-and-concentration">Meditation and Concentration</a></td><td>Mental regulation and cast stability; remains owned here</td></tr><tr><td><a href="/Syrolands-Public/en/game-design/magic/spellbooks-scrolls-and-reagents.html">Spellbooks, scrolls and reagents</a></td><td>Knowledge persistence, physical resources and loot</td></tr><tr><td><a href="/Syrolands-Public/en/game-design/professions/inscription.html">Inscription</a></td><td>Magical engineering and profession specialization</td></tr><tr><td><a href="/Syrolands-Public/en/game-design/magic/presentation.html">Magic presentation</a></td><td>Modular visual grammar and mechanical readability</td></tr><tr><td><a href="/Syrolands-Public/en/game-design/magic/status-and-open-questions.html">Status and open questions</a></td><td>Cross-batch reconciliation and undecided rules</td></tr></tbody></table><p>Institutions, execution Difficulty, wider Mastery, localized casting, casting components, forbidden traditions and meditative states below retain their earlier proposals. Batch 04 does not redesign Necromancy, Voodoo, Chivalry or all magic schools.</p><h2 id="identity-and-principles" tabindex="-1">Identity and principles <a class="header-anchor" href="#identity-and-principles" aria-label="Permalink to &quot;Identity and principles&quot;">​</a></h2><p>Redesign the magic ecosystem from first principles while retaining useful UO ideas. Original spells are a library of ideas that may be retained, reworked, renamed, relocated or removed; no legacy spell is automatically guaranteed a place.</p><table tabindex="0"><thead><tr><th>Concept</th><th>Intended role</th></tr></thead><tbody><tr><td>Magery</td><td>General execution capability</td></tr><tr><td>Spell knowledge</td><td>Techniques the character has permanently learned</td></tr><tr><td>Mastery / proficiency</td><td>Depth of understanding and specialization</td></tr><tr><td>Academies, orders and masters</td><td>Where and how knowledge is acquired</td></tr><tr><td>Inscription</td><td>Magical engineering, encoding and modification</td></tr><tr><td>Meditation</td><td>Internal regulation, concentration and mental states</td></tr></tbody></table><p>The proposal preserves these principles:</p><ol><li>Exploration expands magical vocabulary; high Magery does not automatically grant all spells.</li><li>Specialization improves reliability and depth, rather than merely damage.</li><li>Magic participates in the same localized combat model as melee.</li><li>Forbidden knowledge has social, geographical and mechanical consequences.</li><li>Inscription remains a major crafting and economic profession.</li><li>Meditation contributes active character-building choices beyond mana recovery.</li><li>Concentration creates combat pressure and counterplay.</li><li>Academies are world institutions, not complete-spellbook shops.</li><li>Consumable scrolls provide temporary access without replacing permanent learning.</li><li>Modifiers offer horizontal tactical trade-offs rather than mandatory upgrades.</li><li>Preserve UO&#39;s classless spirit and viable hybrids; do not spend the whole skill cap on separate elemental skills.</li><li>Make useful early magic accessible without tedious macroing, while deep mastery requires long-term exploration and experience.</li></ol><h2 id="knowledge-and-world-institutions" tabindex="-1">Knowledge and world institutions <a class="header-anchor" href="#knowledge-and-world-institutions" aria-label="Permalink to &quot;Knowledge and world institutions&quot;">​</a></h2><h3 id="permanent-learning" tabindex="-1">Permanent learning <a class="header-anchor" href="#permanent-learning" aria-label="Permalink to &quot;Permanent learning&quot;">​</a></h3><p>A properly learned spell becomes permanent character knowledge. A character with Magery 100 might know few spells; another might know many but lack the execution capability to cast difficult ones reliably. Rare knowledge should express the character&#39;s history.</p><p>Knowledge comes from travel, academies, orders, cults, independent or hidden masters, grimoires, ruins, bosses, questlines, world events and supernatural entities. Formal academies do not monopolize every technique. Learning a base spell need not end exploration: another teacher might offer a rare formula or execution method for it.</p><h3 id="four-independent-dimensions" tabindex="-1">Four independent dimensions <a class="header-anchor" href="#four-independent-dimensions" aria-label="Permalink to &quot;Four independent dimensions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dimension</th><th>Meaning</th><th>Illustrative candidates, not final taxonomy</th></tr></thead><tbody><tr><td>Discipline</td><td>What the mage does</td><td>Destruction, Alteration, Conjuration / Invocation, Restoration, Illusion, Abjuration, Divination, Translocation, Necromancy, Voodoo</td></tr><tr><td>Affinity / manifestation</td><td>Phenomenon, medium or expression</td><td>Fire, Frost / Ice, Lightning, Poison, Shadow, Blood, Arcane, Earth, Wind</td></tr><tr><td>Technique</td><td>A learned spell</td><td>Wall of Fire, Incinerate, Napalm, Blink, Flame Ward, Heat Metal, Raise Corpse, Sense Magic</td></tr><tr><td>Tradition / institution</td><td>Who teaches it, under which philosophy and restrictions</td><td>Academy, order, cult, independent master</td></tr></tbody></table><p>A fire specialist need not be a Destruction specialist. Fire can support alteration, protection, conjuration and utility. Do not collapse these dimensions into one generic Fire School containing all fire spells.</p><p><strong>Illustration:</strong> an Ashen Collegium near a volcano might teach destructive fire, heat manipulation, fire protection and ash conjuration. A military war college might overlap in fire while emphasizing siege, smoke, signals, battlefield control and area denial. Partial overlap gives a specialist reasons to travel between institutions. These names do not select actual map locations or create factions.</p><h3 id="admission-lessons-and-standing" tabindex="-1">Admission, lessons and standing <a class="header-anchor" href="#admission-lessons-and-standing" aria-label="Permalink to &quot;Admission, lessons and standing&quot;">​</a></h3><p>Separate requirements to <strong>enter</strong>, requirements to <strong>learn a particular technique</strong>, and conditions to <strong>remain in good standing</strong>. Candidate gates include tuition, Magery thresholds, reputation, faction standing, quests, a boss defeat, proof of technique, rare objects, moral/criminal alignment, PK-only admission, regional trials and prior membership elsewhere.</p><p>Requirements should express identity: a commercial academy charges tuition; a territorial order asks for regional service; a clandestine circle demands complicity; an elite master requests demonstrated technique. Losing favor should normally restrict future teaching, services, ranks or facilities rather than erase already learned knowledge. Partially incompatible affiliations are possible but unresolved.</p><h2 id="magery-execution-and-progression" tabindex="-1">Magery: execution and progression <a class="header-anchor" href="#magery-execution-and-progression" aria-label="Permalink to &quot;Magery: execution and progression&quot;">​</a></h2><h3 id="attempt-floor-versus-execution-difficulty" tabindex="-1">Attempt floor versus execution Difficulty <a class="header-anchor" href="#attempt-floor-versus-execution-difficulty" aria-label="Permalink to &quot;Attempt floor versus execution Difficulty&quot;">​</a></h3><p>Each spell should distinguish <strong>Minimum Magery</strong>, the floor for attempting it, from <strong>Difficulty</strong>, the challenge of successful execution. Eligibility is not competence. Prefer a nonlinear reliability curve; no equation or percentage is adopted.</p><p><strong>Numeric illustrations only:</strong> Minimum Magery 50 could permit frequent failures at 50 and improved reliability above it. Minimum Magery 100 could still describe a spell that fails meaningfully at skill 100 when Difficulty is near or beyond the cap. Major resurrection, large-scale teleportation, dangerous summons, battlefield rituals or forbidden magic are examples of spells beyond reliable generalist mastery, not finalized abilities.</p><p>The tuning direction is unreliable at the low eligible end, competent through the middle and reliable at high skill, with extreme spells still fallible. Costs and modifiers remain unresolved.</p><h3 id="use-based-gain-and-structured-teaching" tabindex="-1">Use-based gain and structured teaching <a class="header-anchor" href="#use-based-gain-and-structured-teaching" aria-label="Permalink to &quot;Use-based gain and structured teaching&quot;">​</a></h3><p>Casting attempts should be able to improve Magery. Relative challenge matters: near-capability spells provide learning opportunities, trivial spells cease to train very high skill, and wildly inappropriate difficulty may also be inefficient. The exact gain curve and whether/how failed attempts contribute are not finalized.</p><p>Academies also offer meaningful progression through exercises, examinations, quests, materials, fees and demonstrations. <strong>Approximately +5 skill per training block</strong> and <strong>roughly Magery 55–60 during an initial focused day</strong> are illustrative progression/pacing targets, not guarantees, configuration values or locked balance.</p><p>Early competence should be accessible; the middle combines teaching and practice; higher skill needs difficult use, specialized teachers, rare training and experience. NPCs should not trivially train a character to 100. This proposal does not change the current <a href="/Syrolands-Public/en/game-design/skills-and-knowledge.html">skill-cap/progression foundation</a>.</p><h3 id="fizzle-versus-interruption" tabindex="-1">Fizzle versus interruption <a class="header-anchor" href="#fizzle-versus-interruption" aria-label="Permalink to &quot;Fizzle versus interruption&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Concept</th><th>Meaning</th><th>Proposed influences</th></tr></thead><tbody><tr><td>Fizzle</td><td>Failure to execute the magical structure correctly</td><td>Magery versus effective Difficulty and relevant modifiers</td></tr><tr><td>Interruption</td><td>Combat pressure disrupts a cast the mage could otherwise execute</td><td>Damage, movement, local trauma, concentration loss, state changes or disabling effects</td></tr></tbody></table><p>Keep these mechanically distinct. Do not infer reagent, mana, cooldown or recovery costs for either outcome until specified.</p><h2 id="mastery-without-rigid-classes" tabindex="-1">Mastery without rigid classes <a class="header-anchor" href="#mastery-without-rigid-classes" aria-label="Permalink to &quot;Mastery without rigid classes&quot;">​</a></h2><p>Do not automatically turn disciplines or affinities into eight or ten separate 0–100 skills. Mastery may live outside the classic skill-cap system; its representation and limits remain open. Preserve viable hybrids and meaningful generalists.</p><p>The primary proposal is <strong>reduced effective Difficulty for advanced relevant spells</strong>, with little benefit to basics and greater specialist usefulness for difficult or extreme techniques. A fire specialist could execute Incinerate more reliably than an equally skilled generalist. Mastery is not a flat damage multiplier.</p><p>Other candidate benefits include reduced backlash, finer area placement, advanced targeting, better information, special execution modes and field-specific advantages. Novice, Adept, Scholar and Master are possible qualitative tiers, not final ranks.</p><p>Progression may consider techniques known, rarity, variety, teachers, institutions visited, quests, practical use and advanced modifiers. Avoid a purchasable spell-count checklist or a fixed wiki shopping route. No count, weight, unlock threshold or incompatibility rule is approved.</p><h2 id="spellbooks-scrolls-and-inscription" tabindex="-1">Spellbooks, scrolls and Inscription <a class="header-anchor" href="#spellbooks-scrolls-and-inscription" aria-label="Permalink to &quot;Spellbooks, scrolls and Inscription&quot;">​</a></h2><p>Batch 04 separates the detailed owners below. Earlier material is retained there; these headings preserve existing incoming links. All new mechanics remain Proposed.</p><h3 id="knowledge-belongs-to-the-character" tabindex="-1">Knowledge belongs to the character <a class="header-anchor" href="#knowledge-belongs-to-the-character" aria-label="Permalink to &quot;Knowledge belongs to the character&quot;">​</a></h3><p>Permanent knowledge remains distinct from the physical book and its loot value. <a href="/Syrolands-Public/en/game-design/magic/spellbooks-scrolls-and-reagents.html#knowledge-belongs-to-the-character">Detailed specification</a>.</p><h3 id="scrolls-provide-temporary-access" tabindex="-1">Scrolls provide temporary access <a class="header-anchor" href="#scrolls-provide-temporary-access" aria-label="Permalink to &quot;Scrolls provide temporary access&quot;">​</a></h3><p>Ordinary casting scrolls provide temporary execution, not automatic permanent learning. <a href="/Syrolands-Public/en/game-design/magic/spellbooks-scrolls-and-reagents.html#scrolls-provide-temporary-access">Detailed specification</a>.</p><h3 id="inscription-as-magical-engineering" tabindex="-1">Inscription as magical engineering <a class="header-anchor" href="#inscription-as-magical-engineering" aria-label="Permalink to &quot;Inscription as magical engineering&quot;">​</a></h3><p>Inscription owns encoding, preservation and controlled transformation of learned structures. <a href="/Syrolands-Public/en/game-design/professions/inscription.html#inscription-as-magical-engineering">Detailed specification</a>.</p><h3 id="horizontal-spell-augmentation" tabindex="-1">Horizontal spell augmentation <a class="header-anchor" href="#horizontal-spell-augmentation" aria-label="Permalink to &quot;Horizontal spell augmentation&quot;">​</a></h3><p>Learned modifiers offer bounded tactical trade-offs, not free upgrade stacking. <a href="/Syrolands-Public/en/game-design/magic/variants-and-glyphs.html#horizontal-spell-augmentation">Detailed specification</a>.</p><h3 id="prepared-configurations-and-crafted-grimoires" tabindex="-1">Prepared configurations and crafted grimoires <a class="header-anchor" href="#prepared-configurations-and-crafted-grimoires" aria-label="Permalink to &quot;Prepared configurations and crafted grimoires&quot;">​</a></h3><p>Prepared variants, permanent knowledge and physical grimoire benefits are different concepts. <a href="/Syrolands-Public/en/game-design/magic/variants-and-glyphs.html#prepared-configurations-and-crafted-grimoires">Detailed specification</a>.</p><h2 id="localized-magic-and-injury" tabindex="-1">Localized magic and injury <a class="header-anchor" href="#localized-magic-and-injury" aria-label="Permalink to &quot;Localized magic and injury&quot;">​</a></h2><p>Magic must engage the same anatomical model as weapons; each spell needs an impact/damage/trauma profile appropriate to its form rather than just a generic HP number. Retain <a href="/Syrolands-Public/en/game-design/combat/damage.html">global damage versus Local Trauma</a>, <a href="/Syrolands-Public/en/game-design/combat/body-regions.html">independent regions</a> and server-resolved outcomes.</p><table tabindex="0"><thead><tr><th>Illustrative form</th><th>Candidate interaction, not an implemented rule</th></tr></thead><tbody><tr><td>Projectile</td><td>A specific anatomical location selected by impact profile/targeting</td></tr><tr><td>Explosion</td><td>Trauma distributed over multiple regions</td></tr><tr><td>Ground AoE</td><td>Disproportionate leg/foot exposure; feet are not newly approved standalone body regions</td></tr><tr><td>Curse</td><td>Specific limb impairment</td></tr><tr><td>Thermal</td><td>Burns, tissue damage or heated armor</td></tr><tr><td>Frost</td><td>Stiffness, mobility impairment, fragility or local freezing</td></tr><tr><td>Lightning</td><td>Spasms, temporary control loss or precision penalties</td></tr><tr><td>Kinetic / force</td><td>Blunt trauma, fractures or knockback</td></tr><tr><td>Acid / corrosion</td><td>Armor wear and tissue damage</td></tr><tr><td>Necromantic / supernatural</td><td>Vitality effects that need not behave like blunt/slash trauma</td></tr></tbody></table><p>Do not automatically apply the legacy melee armor adapter, residual ×2 trauma, one-primary-region rule or current HP-loss gate to every magic form. Exposure, armor/resistance, multi-region budgets, repeated area contacts and non-damaging curses need their own explicit contracts. The melee slice retains its existing scope; this proposal does not implement propagation or alter its tests.</p><h3 id="normal-and-focused-cast" tabindex="-1">Normal and Focused Cast <a class="header-anchor" href="#normal-and-focused-cast" aria-label="Permalink to &quot;Normal and Focused Cast&quot;">​</a></h3><p><strong>Proposed:</strong> Normal Cast uses the spell&#39;s natural anatomical profile. Focused Cast attempts a known limb, requires sufficient information/Anatomy, and adds meaningful execution Difficulty, time, resources or another cost. Selection remains intent, not a guaranteed hit/location. Exact interaction with <a href="/Syrolands-Public/en/game-design/combat/targeting.html">targeting</a> is unresolved; do not copy its experimental 50% melee probability into casting.</p><p><strong>Illustration:</strong> an informed mage aims Ice Lance at the target&#39;s anatomical left leg and accepts greater execution difficulty. Relevant Mastery might offset part of the added difficulty. Flash Freeze could exploit a Wounded leg, Combust Wound damaged tissue, or a targeted curse an already weak arm. These are proposed interactions supporting tactical reading, not a DPS rotation or approved wound multipliers.</p><p>Current experimental <a href="/Syrolands-Public/en/game-design/skills-and-knowledge.html">Anatomy disclosure</a> is not automatically the final targeting prerequisite for magic. Determine required knowledge, freshness and visibility before designing its contract.</p><h3 id="casting-components-and-injured-limbs" tabindex="-1">Casting components and injured limbs <a class="header-anchor" href="#casting-components-and-injured-limbs" aria-label="Permalink to &quot;Casting components and injured limbs&quot;">​</a></h3><p>Candidate component tags include Verbal, Gestural, Focused and Ritual; spells need not depend on the same components. Severe head trauma might destabilize concentration/Meditation; arm injury might penalize gestures; chest trauma might affect breath, endurance, long channels or rituals. Tags could interact with silence and restraint.</p><p>One-Handed Casting and Silent Casting are examples of rare learned techniques, not automatic generic perks. Exact thresholds, alternatives and component rules are unresolved. These proposed penalties do <strong>not</strong> supersede <a href="/Syrolands-Public/en/game-design/combat/disability.html">Slice 0&#39;s limited disability rules</a> or authorize extra functional penalties in the current melee implementation.</p><h2 id="meditation-and-concentration" tabindex="-1">Meditation and Concentration <a class="header-anchor" href="#meditation-and-concentration" aria-label="Permalink to &quot;Meditation and Concentration&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/magic/meditation-and-concentration.html">Player guide</a>. This section remains the single owner of mental regulation and cast stability; <a href="/Syrolands-Public/en/game-design/magic/memory-and-familiarity.html">Active Memory</a> owns loadout capacity and reference rules.</p><p><strong>Batch 04, Proposed:</strong> Meditation can organize and rearrange Active Memory, prepare difficult patterns and recover mental readiness. Higher Meditation may make loadout changes faster/safer and Concentration recovery stronger; no formula, instantaneous in-combat swap or free preparation is granted. Damage, movement, local trauma, blunt/stun effects, repeated pressure, fatigue, item traits and difficult variants are pressure candidates, not newly implemented penalties. Preserve the distinction below between execution fizzle and interruption; Concentration is not automatically another capped skill.</p><p>Meditation is mental control and internal magical regulation as well as mana recovery. Skill represents capacity; specific meditative techniques represent knowledge. Advanced techniques may be taught by monasteries, military orders, academies, cults or hidden masters, with precise acquisition/unlock rules still open. States are not ordinary spells and should be commitments with trade-offs, not free buff toggles.</p><table tabindex="0"><thead><tr><th>Illustrative state</th><th>Possible benefit</th><th>Possible commitment/cost</th></tr></thead><tbody><tr><td>Trance of Stillness</td><td>Strong mana recovery, stable concentration, lower Difficulty</td><td>Immobility/severe movement penalty, reduced awareness, exit delay</td></tr><tr><td>Battle Meditation</td><td>Moderate recovery under combat pressure, interruption resistance</td><td>Stamina penalty, reduced mobility or another trade-off</td></tr><tr><td>Empty Mind</td><td>Resistance to Illusion, Fear, Charm or mental Voodoo</td><td>Weaker offensive Divination or summon maintenance</td></tr><tr><td>Flow State</td><td>More stable coherent discipline/affinity use</td><td>Switching fields breaks the state</td></tr><tr><td>Deep Channel</td><td>Access to extremely difficult attempts</td><td>Higher mana use and vulnerability</td></tr><tr><td>Ember Trance</td><td>Fire-specialist stability and lower effective Difficulty</td><td>Other affinities may become harder</td></tr></tbody></table><p>Ember Trance illustrates interaction between Fire Mastery and strong Meditation, not a finalized stance or requirement.</p><h3 id="concentration-under-pressure" tabindex="-1">Concentration under pressure <a class="header-anchor" href="#concentration-under-pressure" aria-label="Permalink to &quot;Concentration under pressure&quot;">​</a></h3><p>Concentration is a proposed additional gameplay layer, not necessarily another visible 0–100 skill. It might be a dynamic resource, internal state or semi-visible meter; representation and UI are unresolved.</p><p>Candidate influences include hits, movement, local trauma, target changes, summon maintenance, mental effects, complex casts and interruptions. Meditation may restore, stabilize or preserve it. Advanced casting may require sufficient Mana, Magery <strong>and</strong> Concentration. Remaining mana alone should not make a pressured mage behave identically to an undisturbed one; melee can disrupt control before depleting health. Recovery, decay, thresholds and interruption formulas are not selected.</p><h2 id="forbidden-traditions" tabindex="-1">Forbidden traditions <a class="header-anchor" href="#forbidden-traditions" aria-label="Permalink to &quot;Forbidden traditions&quot;">​</a></h2><h3 id="necromancy" tabindex="-1">Necromancy <a class="header-anchor" href="#necromancy" aria-label="Permalink to &quot;Necromancy&quot;">​</a></h3><p>Proposed identity: death, corpses, souls, reanimation, vitality transfer and post-mortem states. Knowledge might be found in crypts, cults, hidden masters, forbidden grimoires, ruins and undead entities, rather than a normal public academy catalogue. Learning may affect institutional/faction relationships. Do not introduce generic “evil points” without a wider world-design decision.</p><h3 id="voodoo-sympathetic-magic-and-personal-links" tabindex="-1">Voodoo: sympathetic magic and personal links <a class="header-anchor" href="#voodoo-sympathetic-magic-and-personal-links" aria-label="Permalink to &quot;Voodoo: sympathetic magic and personal links&quot;">​</a></h3><p>Voodoo has a distinct proposed identity: using personal materials/remnants to establish a connection to a particular character. It is not a synonym for Necromancy.</p><p><strong>Illustrative loop:</strong> kill or discover another player&#39;s corpse → obtain a personal remnant (head, blood, hair, bone) through an eligible interaction → perform a ritual at an altar → create a Voodoo Effigy linked to that character → use effects under defined conditions. Anatomy, Forensics, Voodoo knowledge, Carpentry and other crafting skills are possible contributors, not assigned requirements. Ownership, extraction eligibility and altar recipes remain unresolved.</p><table tabindex="0"><thead><tr><th>Illustrative effect</th><th>Possible purpose</th></tr></thead><tbody><tr><td>Needle of Agony</td><td>Remote/semi-remote damage</td></tr><tr><td>Withering Curse</td><td>Temporary stat or regeneration reduction</td></tr><tr><td>Limping Hex</td><td>Specific leg impairment</td></tr><tr><td>Silence of the Tongue</td><td>Casting disruption</td></tr><tr><td>Marked Blood</td><td>Directional tracking</td></tr><tr><td>Dream Fever</td><td>Gradual debuff</td></tr><tr><td>Binding Thread</td><td>Interference with Recall/Gate/Translocation</td></tr><tr><td>Shared Pain</td><td>A form of linked incoming damage</td></tr><tr><td>Effigy Rupture</td><td>Powerful one-use effect consuming the effigy</td></tr></tbody></table><p><strong>Counterplay is required by the proposal:</strong> one death must not enable unlimited permanent harassment. Candidate constraints include decaying links/remnant potency, proximity for strongest effects, material consumption, bounded maintained links, Divination detection/identification, purification to sever links and defensive wards. Exact durations, range, costs, caps and victim protections remain unresolved; the examples grant no unrestricted remote-PvP capability.</p><p>The intended fantasy—“that enemy possesses a part of me”—connects PvP, corpses, Anatomy/Forensics, housing, Carpentry, ritual crafting, Inscription, Divination and counter-magic. It still needs a coherent anti-grief policy before implementation.</p><h2 id="illustrative-character-identity" tabindex="-1">Illustrative character identity <a class="header-anchor" href="#illustrative-character-identity" aria-label="Permalink to &quot;Illustrative character identity&quot;">​</a></h2><p>All numbers and interactions here are illustrative, not build requirements or tested balance.</p><table tabindex="0"><thead><tr><th>Character A</th><th>Character B</th></tr></thead><tbody><tr><td>Magery 92, Meditation 85, Anatomy 70</td><td>Magery 100, Meditation 30, Anatomy 0</td></tr><tr><td>High Fire Mastery; Incinerate and an advanced fire modifier learned</td><td>No Fire Mastery</td></tr><tr><td>Might sustain a fire state, inspect an injured leg and attempt a more difficult focused Incinerate, partly offset by Mastery</td><td>Stronger general execution does not automatically confer A&#39;s anatomical targeting, fire reliability or concentration control</td></tr></tbody></table><p>A remains vulnerable to interruption through lost Concentration. B&#39;s actual spell knowledge is unspecified, not inferred from Magery 100. The example shows different play identities without rigid classes or a claim that either build is universally stronger.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p>All entries remain <strong>Unresolved</strong>; this list is not an approved delivery schedule.</p><table tabindex="0"><thead><tr><th>Area</th><th>Decisions still needed</th></tr></thead><tbody><tr><td>Execution</td><td>Exact nonlinear success formula; Minimum Magery versus Difficulty; fizzle costs; full/partial/no reagent consumption on failure; distinction from interruption costs</td></tr><tr><td>Progression</td><td>Skill-gain formula, challenge bounds and failed-attempt gain; early-game pacing; teaching increments/limits</td></tr><tr><td>Mastery</td><td>Numeric/tiered/hidden/visible/hybrid form, relation to skill cap, progression weights and benefits; specialization limits</td></tr><tr><td>Taxonomy and institutions</td><td>Final disciplines/affinities, partially exclusive affiliations and remaining-standing rules; which original UO spells survive</td></tr><tr><td>Books and scrolls</td><td>Specific personal-book protection/replacement versus loot; exact scroll restrictions; which forbidden spells can be scrolled; scribe knowledge/recipe requirements</td></tr><tr><td>Augmentation</td><td>Slot counts, prepared versus always-available configuration, switching/consumption rules and distinct crafted-book loss policies</td></tr><tr><td>Concentration</td><td>Representation, recovery/decay, movement interaction, summon/target-change pressure and interruption formulas</td></tr><tr><td>Localized casting</td><td>Per-spell hit/trauma profiles, armor/resistance interaction, multi-region allocation, focused penalties and Anatomy&#39;s exact targeting role</td></tr><tr><td>Components</td><td>Verbal/gestural/focused/ritual tags, injury/silence/restraint interactions, one-handed/silent casting rules</td></tr><tr><td>Voodoo</td><td>Link duration/range/conditions and counters; corpse-remnant extraction; anti-grief protections; Forensics role; altar crafting requirements</td></tr><tr><td>Meditation</td><td>Learned/discovered/skill-threshold unlocks; exact restrictions, costs and trade-offs; Mastery/state interaction</td></tr><tr><td>Presentation</td><td>Asset acquisition, renderer compatibility, visibility/disclosure and a future effect contract; no chosen pipeline</td></tr></tbody></table><h2 id="proposed-environmental-interaction" tabindex="-1">Proposed environmental interaction <a class="header-anchor" href="#proposed-environmental-interaction" aria-label="Permalink to &quot;Proposed environmental interaction&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/living-world.html#magic-and-tactical-preparation">Living world and materials</a> proposes shared material responses to heat, water, cold, lightning, wind and earth effects. Fireball supplies generic heat/ignition stimuli rather than object-specific burn scripts. Environmental spell effects, weather integration and tactical terrain changes remain Proposed; the candidate tree/grass prototype is not implementation authorization or a final spell list.</p><h2 id="integration-boundary-and-sources" tabindex="-1">Integration boundary and sources <a class="header-anchor" href="#integration-boundary-and-sources" aria-label="Permalink to &quot;Integration boundary and sources&quot;">​</a></h2><p><strong>Authority:</strong> client intent might request a focused cast; ModernUO must resolve eligibility, targets, affected tiles, duration, damage, trauma, status and collision/area effects. Synchronized data would contain only server-approved information; ClassicUO would present effects/cues. No client animation or particle collision may decide gameplay.</p><p>Visual ambitions are a separate technical concern; stock UO effects must not define spell design. No effect ID, packet, persistence schema or renderer has been allocated here.</p><p><strong>Current implementation and gap:</strong> existing documentation records natural localized melee and experimental Anatomy in current slice. It does not establish this magic ecosystem as implemented. Neither the original integration nor Batch 04 establishes a fresh audit of legacy spell code or changes its behavior. See the inheritance evidence boundaries. Permanent learning, institutions, mastery, scroll/Inscription changes, concentration and localized casting need later approved technical designs, bounded implementations and playtests. New magic remains outside the current slice; no accepted ADR is superseded by this proposal.</p><p><strong>Provenance:</strong> user-supplied Magic Redesign Documentation Prompt v0.1, sections 1–25, integrated on 2026-10-04. Source sections 1–3 map to knowledge/institutions; 4–7 to execution/progression/mastery; 8–13 to books/scrolls/Inscription; 14–15 and 18 to localized casting; 16–17 and 21 to Meditation/Concentration; 19–20 to forbidden traditions; 22–24 to identity/principles/open questions; 25 to the separate renderer concern. Historical combat sources remain unchanged.</p><h2 id="profession-and-item-quality-proposals" tabindex="-1">Profession and item-quality proposals <a class="header-anchor" href="#profession-and-item-quality-proposals" aria-label="Permalink to &quot;Profession and item-quality proposals&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/professions/alchemy.html">Alchemy</a> and <a href="/Syrolands-Public/en/game-design/professions/cooking.html">Cooking</a> propose preparations/food that may interact with recovery or Concentration; <a href="/Syrolands-Public/en/game-design/professions/tinkering.html">Tinkering</a> leaves magical construct binding as a future possibility. <a href="/Syrolands-Public/en/game-design/items/itemization-and-craft-quality.html">Item traits and latent resonance</a> need compatibility and counterplay rather than implied spell effects.</p><p>The <a href="/Syrolands-Public/en/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">profession reconciliation register</a> keeps global teaching/gain direction separate from Magery&#39;s illustrative training blocks and execution Difficulty. No numeric pacing, new Concentration skill, Inscription rule or spellbook-loss exception is accepted by Batch 01.</p><h2 id="batch-02-progression-and-int-reconciliation" tabindex="-1">Batch 02 progression and INT reconciliation <a class="header-anchor" href="#batch-02-progression-and-int-reconciliation" aria-label="Permalink to &quot;Batch 02 progression and INT reconciliation&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/characters/skills-and-skillcap.html#reconciliation-and-open-questions">Skills &amp; Skillcap</a> centralizes the general Proposed gain/cap/teacher framework, including the 80–90 Very slow band. The +5 blocks and 55–60 first-day examples above remain magic-specific illustrations, not general rates. Reliable routine low-skill work and fallible advanced spell Difficulty need deliberate reconciliation; this addition changes neither the spell model nor its existing text.</p><p><a href="/Syrolands-Public/en/game-design/characters/stats.html#int-broader-mental-capability">INT direction</a> proposes cognition, mental resilience and magical resource capability beyond mana size. Its relationship with Meditation, Concentration, spell knowledge and mental states remains Unresolved; no complete INT system or new skill is implied.</p><h2 id="batch-03-combat-pressure-boundary" tabindex="-1">Batch 03 combat pressure boundary <a class="header-anchor" href="#batch-03-combat-pressure-boundary" aria-label="Permalink to &quot;Batch 03 combat pressure boundary&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/combat/stamina-and-reactive-combat.html#concentration-pressure">Stamina and reactive combat</a> links damage, local trauma, movement, repeated pressure, stun/impact and weapon-trait candidates to the existing Proposed Concentration design. This does not select interruption formulas, create stun mechanics, redefine fizzle, or require a standalone Concentration skill. Magic remains the canonical owner of these distinctions.</p><h2 id="batch-04-provenance-and-progression" tabindex="-1">Batch 04 provenance and progression <a class="header-anchor" href="#batch-04-provenance-and-progression" aria-label="Permalink to &quot;Batch 04 provenance and progression&quot;">​</a></h2><p>Batch 04 (A–X) adds Core Patterns, bounded glyphs, per-pattern Familiarity, Active Memory, INT cognitive workspace, material risk, Inscription and modular visuals. The <a href="/Syrolands-Public/en/game-design/magic/status-and-open-questions.html">reconciliation register</a> records changed emphasis and unresolved conflicts. Familiarity does not consume skillcap and is distinct from broader discipline/affinity Mastery. Under the <a href="/Syrolands-Public/en/game-design/characters/skills-and-skillcap.html">Proposed no-ordinary-120 direction</a>, Magery 100 is technical mastery, not magical completion: rare patterns, schools, modifiers, practice, preparation, grimoires, rituals, regional knowledge, rare reagents, player execution and Inscription sustain long-term progression. No ordinary skill cap or spell availability is changed.</p>',105)])])}const h=t(r,[["render",o]]);export{u as __pageData,h as default};
